      const x0 = Math.floor(fx), y0 = Math.floor(fy);
      const tx = smooth(fx-x0), ty = smooth(fy-y0);
      const x1 = (x0+1)%cells, y1 = (y0+1)%cells;
      const v = lerp(lerp(grid[y0*cells+x0], grid[y0*cells+x1], tx), lerp(grid[y1*cells+x0], grid[y1*cells+x1], tx), ty);
      data[y*size+x] += v*amp;
    }
    total += amp; amp *= 0.55;
  }
