import * as THREE from 'three';

export const WAVES = [
  { dir: [1.0, 0.28], amp: 0.75, wavelength: 32, speed: 1.0, sharp: 1.3 },
  { dir: [0.80, -0.60], amp: 0.40, wavelength: 17.5, speed: 1.02, sharp: 1.45 },
  { dir: [0.96, 0.28], amp: 0.21, wavelength: 9.2, speed: 1.12, sharp: 1.5 },
  { dir: [0.52, 0.85], amp: 0.125, wavelength: 5.4, speed: 1.22, sharp: 1.35 },
  { dir: [-0.18, 0.98], amp: 0.08, wavelength: 3.1, speed: 1.3, sharp: 1.2 },
];

const G = 9.81;

export const WAVE_DATA = WAVES.map((w) => {
  const [dx, dz] = normalize(w.dir);
  const k = (2 * Math.PI) / w.wavelength;
  const omega = w.speed * Math.sqrt(G * k);
  return { dx, dz, k, omega, amp: w.amp, sharp: w.sharp, p: w.sharp };
});

export function waveHeight(x, z, t) {
  let h = 0;
  for (const w of WAVE_DATA) {
    const ph = w.k * (w.dx * x + w.dz * z) + w.omega * t;
    const u = 0.5 + 0.5 * Math.sin(ph);
    h += w.amp * (2 * Math.pow(u, w.p) - 1);
  }
  return h;
}

export function waveGradient(x, z, t) {
  let gx = 0, gz = 0;
  for (const w of WAVE_DATA) {
    const ph = ...;
    const u = ...;
    const du = 0.5 * Math.cos(ph);
    const d = w.amp * 2 * w.p * Math.pow(u, w.p - 1) * du * w.k;  // dy/dph * dph/dx...
    gx += d * w.dx; gz += d * w.dz;
  }
  return [gx, gz];
}

export function waveNormal(x, z, t) {
  const [gx, gz] = waveGradient(x, z, t);
  return new THREE.Vector3(-gx, 1, -gz).normalize();
}
