// Shared ocean-wave field. The exact same parameters are used from JavaScript
// (to place the surfer on the surface) and from GLSL (to displace + shade the
// ocean), so the board always sits on the water.

const G = 9.81;

function normalize2(x, y) {
  const l = Math.hypot(x, y);
  return [x / l, y / l];
}

// amp: wave height, wavelength: crest distance, speed: dispersion multiplier,
// sharp: >1 sharpens crests and flattens troughs (classic ocean profile).
export const WAVES = [
  { dir: [1.0, 0.26], amp: 0.72, wavelength: 31.0, speed: 1.0, sharp: 1.32 },
  { dir: [0.82, -0.58], amp: 0.40, wavelength: 17.5, speed: 1.03, sharp: 1.45 },
  { dir: [0.96, 0.29], amp: 0.21, wavelength: 9.2, speed: 1.12, sharp: 1.5 },
  { dir: [0.52, 0.85], amp: 0.125, wavelength: 5.4, speed: 1.22, sharp: 1.35 },
  { dir: [-0.18, 0.98], amp: 0.082, wavelength: 3.1, speed: 1.3, sharp: 1.22 },
];

export const WAVE_DATA = WAVES.map((w) => {
  const [dx, dz] = normalize2(w.dir[0], w.dir[1]);
  const k = (2 * Math.PI) / w.wavelength;
  return {
    dx,
    dz,
    k,
    omega: w.speed * Math.sqrt(G * k),
    amp: w.amp,
    p: w.sharp,
  };
});

/** Surface height at (x, z) for time t. */
export function waveHeight(x, z, t) {
  let h = 0;
  for (const w of WAVE_DATA) {
    const ph = w.k * (w.dx * x + w.dz * z) + w.omega * t;
    const u = 0.5 + 0.5 * Math.sin(ph);
    h += w.amp * (2 * Math.pow(u, w.p) - 1);
  }
  return h;
}

/** Gradient (dh/dx, dh/dz) at (x, z) for time t. */
export function waveGradient(x, z, t) {
  let gx = 0;
  let gz = 0;
  for (const w of WAVE_DATA) {
    const ph = w.k * (w.dx * x + w.dz * z) + w.omega * t;
    const u = Math.min(1, Math.max(1e-4, 0.5 + 0.5 * Math.sin(ph)));
    const d = w.amp * 2 * w.p * Math.pow(u, w.p - 1) * (0.5 * Math.cos(ph)) * w.k;
    gx += d * w.dx;
    gz += d * w.dz;
  }
  return [gx, gz];
}

/** Unit surface normal at (x, z) for time t. */
export function waveNormal(x, z, t, target) {
  const [gx, gz] = waveGradient(x, z, t);
  const out = target || { x: 0, y: 0, z: 0 };
  const inv = 1 / Math.sqrt(gx * gx + 1 + gz * gz);
  out.x = -gx * inv;
  out.y = inv;
  out.z = -gz * inv;
  return out;
}

const f = (v) => {
  const s = Number(v).toFixed(7);
  return s.includes('.') ? s : `${s}.0`;
};

/** GLSL twin of waveHeight()/waveGradient(). */
export const WAVE_GLSL = /* glsl */ `
void waveEval(vec2 p, float t, out float h, out vec2 grad) {
  h = 0.0;
  grad = vec2(0.0);
${WAVE_DATA.map(
  (w) => /* glsl */ `
  {
    float ph = ${f(w.k)} * (${f(w.dx)} * p.x + ${f(w.dz)} * p.y) + ${f(w.omega)} * t;
    float u = clamp(0.5 + 0.5 * sin(ph), 1e-4, 1.0);
    float pu = pow(u, ${f(w.p - 1)});
    h += ${f(w.amp)} * (2.0 * u * pu - 1.0);
    float d = ${f(w.amp * 2 * w.p * w.k)} * pu * (0.5 * cos(ph));
    grad += vec2(${f(w.dx)}, ${f(w.dz)}) * d;
  }`,
).join('')}
}
`;

// Every texture used by the scene is generated in code (no external assets).
import * as THREE from 'three';

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function smoothstep(t) {
  return t * t * (3 - 2 * t);
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function canvasTexture(canvas, { srgb = false } = {}) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  tex.needsUpdate = true;
  return tex;
}

/** Seamless tiling value-noise texture (RGBA, all channels identical). */
export function makeNoiseTexture(size = 256, seed = 20240517) {
  const rnd = mulberry32(seed);
  const field = new Float32Array(size * size);
  let amp = 1;
  let total = 0;
  for (let octave = 0; octave < 5; octave++) {
    const cells = 4 << octave;
    const grid = new Float32Array(cells * cells);
    for (let i = 0; i < grid.length; i++) grid[i] = rnd();
    for (let y = 0; y < size; y++) {
      const fy = (y / size) * cells;
      const y0 = Math.floor(fy);
      const ty = smoothstep(fy - y0);
      const y1 = (y0 + 1) % cells;
      for (let x = 0; x < size; x++) {
        const fx = (x / size) * cells;
        const x0 = Math.floor(fx);
        const tx = smoothstep(fx - x0);
        const x1 = (x0 + 1) % cells;
        const v = lerp(
          lerp(grid[y0 * cells + x0], grid[y0 * cells + x1], tx),
          lerp(grid[y1 * cells + x0], grid[y1 * cells + x1], tx),
          ty,
        );
        field[y * size + x] += v * amp;
      }
    }
    total += amp;
    amp *= 0.52;
  }

  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  for (let i = 0; i < size * size; i++) {
    const v = Math.round(Math.min(1, Math.max(0, field[i] / total)) * 255);
    img.data[i * 4] = v;
    img.data[i * 4 + 1] = v;
    img.data[i * 4 + 2] = v;
    img.data[i * 4 + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  return canvasTexture(canvas);
}

/** Soft round puff used for spray droplets (alpha only). */
export function makeDropTexture(size = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const g = ctx.createRadialGradient(
    size / 2,
    size / 2,
    0,
    size / 2,
    size / 2,
    size / 2,
  );
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.35, 'rgba(255,255,255,0.72)');
  g.addColorStop(0.72, 'rgba(255,255,255,0.18)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.NoColorSpace;
  return tex;
}

/** Big radial glow used for the sun halo. */
export function makeGlowTexture(size = 256) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const g = ctx.createRadialGradient(
    size / 2,
    size / 2,
    0,
    size / 2,
    size / 2,
    size / 2,
  );
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.12, 'rgba(255,246,214,0.85)');
  g.addColorStop(0.32, 'rgba(255,226,170,0.32)');
  g.addColorStop(0.62, 'rgba(255,214,150,0.09)');
  g.addColorStop(1, 'rgba(255,210,150,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

/** Puffy cumulus cloud sprite with soft edges. */
export function makeCloudTexture(seed = 7) {
  const rnd = mulberry32(seed);
  const w = 512;
  const h = 256;
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');

  const blobs = 22;
  for (let i = 0; i < blobs; i++) {
    const cx = w * (0.16 + 0.68 * rnd());
    const cy = h * (0.52 + 0.26 * (rnd() - 0.5) * 2);
    const r = h * (0.12 + 0.3 * rnd()) * (1 - Math.abs(cx / w - 0.5) * 0.8);
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
    const a = 0.32 + 0.3 * rnd();
    g.addColorStop(0, `rgba(255,255,255,${a})`);
    g.addColorStop(0.55, `rgba(255,255,255,${a * 0.55})`);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  }

  // flat-ish base, like a cumulus cloud
  ctx.globalCompositeOperation = 'destination-out';
  const base = ctx.createLinearGradient(0, h * 0.62, 0, h);
  base.addColorStop(0, 'rgba(0,0,0,0)');
  base.addColorStop(1, 'rgba(0,0,0,0.85)');
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, w, h);

  // fade the sprite edges so it blends into the sky
  const side = ctx.createLinearGradient(0, 0, w, 0);
  side.addColorStop(0, 'rgba(0,0,0,1)');
  side.addColorStop(0.16, 'rgba(0,0,0,0)');
  side.addColorStop(0.84, 'rgba(0,0,0,0)');
  side.addColorStop(1, 'rgba(0,0,0,1)');
  ctx.fillStyle = side;
  ctx.fillRect(0, 0, w, h);
  ctx.globalCompositeOperation = 'source-over';

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

import * as THREE from 'three';
import { WAVE_GLSL } from './waves.js';
import { makeNoiseTexture } from './textures.js';

const VERT = /* glsl */ `
uniform float uTime;
varying vec3 vWorldPos;
varying float vHeight;
${WAVE_GLSL}
void main() {
  vec3 pos = position;
  float h;
  vec2 g;
  waveEval(pos.xz, uTime, h, g);
  pos.y += h;
  vHeight = h;
  vec4 wp = modelMatrix * vec4(pos, 1.0);
  vWorldPos = wp.xyz;
  gl_Position = projectionMatrix * viewMatrix * wp;
}
`;

const FRAG = /* glsl */ `
uniform float uTime;
uniform vec3 uCamPos;
uniform vec3 uSunDir;
uniform vec3 uSunColor;
uniform vec3 uSkyTop;
uniform vec3 uHorizon;
uniform vec3 uDeep;
uniform vec3 uShallow;
uniform vec3 uFoamColor;
uniform vec2 uFogRange;
uniform sampler2D uNoise;
varying vec3 vWorldPos;
varying float vHeight;
${WAVE_GLSL}
void main() {
  // per-pixel wave normal: smooth shading + exact match with the displacement
  float h;
  vec2 grad;
  waveEval(vWorldPos.xz, uTime, h, grad);
  vec3 n = normalize(vec3(-grad.x, 1.0, -grad.y));

  // fine ripple detail from the noise texture
  vec2 uv = vWorldPos.xz * 0.13 + vec2(uTime * 0.014, uTime * 0.009);
  float e = 0.085;
  float r0 = texture2D(uNoise, uv).r;
  float rx = texture2D(uNoise, uv + vec2(e, 0.0)).r;
  float rz = texture2D(uNoise, uv + vec2(0.0, e)).r;
  n = normalize(n + vec3((r0 - rx), 0.0, (r0 - rz)) * 2.6);

  vec3 viewDir = normalize(uCamPos - vWorldPos);
  float fres = pow(1.0 - clamp(dot(n, viewDir), 0.0, 1.0), 4.0);

  // water body colour: deep in troughs, lighter over the crests
  vec3 base = mix(uDeep, uShallow, clamp(h * 0.5 + 0.34, 0.0, 1.0));
  base += uShallow * 0.35 * smoothstep(0.45, 1.35, h);

  // sky reflection
  vec3 refl = reflect(-viewDir, n);
  float sky = clamp(refl.y * 1.7, 0.0, 1.0);
  vec3 skyCol = mix(uHorizon, uSkyTop, pow(sky, 0.7));

  vec3 col = mix(base, skyCol, clamp(0.1 + fres * 0.95, 0.0, 1.0));

  // sun sparkle: tight glint + broad sheen
  vec3 halfV = normalize(uSunDir + viewDir);
  float ndh = max(dot(n, halfV), 0.0);
  col += uSunColor * (pow(ndh, 320.0) * 2.6 + pow(ndh, 26.0) * 0.16);

  // foam on steep faces and crests
  float foamA = texture2D(uNoise, vWorldPos.xz * 0.072 + vec2(uTime * 0.006, -uTime * 0.0045)).r;
  float foamB = texture2D(uNoise, vWorldPos.xz * 0.185 - vec2(uTime * 0.012, uTime * 0.008)).r;
  float crest = smoothstep(0.35, 1.15, h);
  float steep = smoothstep(0.012, 0.075, 1.0 - n.y);
  float foam = crest * smoothstep(0.34, 0.86, foamA * 0.62 + foamB * 0.5);
  foam += steep * smoothstep(0.44, 0.88, foamB) * 0.62;
  foam = clamp(foam, 0.0, 1.0);
  col = mix(col, uFoamColor, foam * 0.88);

  // haze into the horizon so the water meets the sky seamlessly
  float dist = length(uCamPos - vWorldPos);
  float fogF = smoothstep(uFogRange.x, uFogRange.y, dist);
  col = mix(col, uHorizon, fogF);

  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createOcean({ palette, sunDir, size = 460, segments = 340 }) {
  const geometry = new THREE.PlaneGeometry(size, size, segments, segments);
  geometry.rotateX(-Math.PI / 2);

  const uniforms = {
    uTime: { value: 0 },
    uCamPos: { value: new THREE.Vector3() },
    uSunDir: { value: sunDir.clone() },
    uSunColor: { value: new THREE.Color(palette.sunColor) },
    uSkyTop: { value: new THREE.Color(palette.skyTop) },
    uHorizon: { value: new THREE.Color(palette.skyHorizon) },
    uDeep: { value: new THREE.Color(palette.oceanDeep) },
    uShallow: { value: new THREE.Color(palette.oceanShallow) },
    uFoamColor: { value: new THREE.Color(palette.foam) },
    uFogRange: { value: new THREE.Vector2(70, 235) },
    uNoise: { value: makeNoiseTexture(256) },
  };

  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: VERT,
    fragmentShader: FRAG,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.renderOrder = -5;

  return {
    mesh,
    update(t, camera) {
      uniforms.uTime.value = t;
      uniforms.uCamPos.value.copy(camera.position);
    },
  };
}

import * as THREE from 'three';
import { makeCloudTexture, makeGlowTexture } from './textures.js';

const SKY_VERT = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const SKY_FRAG = /* glsl */ `
uniform vec3 uTop;
uniform vec3 uHorizon;
uniform vec3 uSunColor;
uniform vec3 uSunDir;
varying vec3 vDir;
void main() {
  vec3 d = normalize(vDir);
  float y = d.y;
  vec3 col = mix(uHorizon, uTop, pow(clamp(y, 0.0, 1.0), 0.58));
  float sd = max(dot(d, uSunDir), 0.0);
  col += uSunColor * pow(sd, 5.0) * 0.14;
  col += uSunColor * pow(sd, 40.0) * 0.55;
  col = mix(col, uHorizon * 1.06, smoothstep(0.16, -0.06, y));
  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

const GULL_VERT = /* glsl */ `
varying vec3 vNormalW;
void main() {
  vNormalW = normalize(mat3(modelMatrix) * normal);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const GULL_FRAG = /* glsl */ `
uniform vec3 uColor;
uniform vec3 uSunDir;
uniform vec3 uSkyTop;
uniform vec3 uHorizon;
varying vec3 vNormalW;
void main() {
  vec3 n = normalize(vNormalW);
  float lit = clamp(dot(n, uSunDir) * 0.5 + 0.5, 0.0, 1.0);
  vec3 col = uColor * mix(0.55, 1.15, lit);
  col = mix(col, uSkyTop, 0.16);
  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createSky({ palette, sunDir }) {
  const group = new THREE.Group();

  const uniforms = {
    uTop: { value: new THREE.Color(palette.skyTop) },
    uHorizon: { value: new THREE.Color(palette.skyHorizon) },
    uSunColor: { value: new THREE.Color(palette.sunColor) },
    uSunDir: { value: sunDir.clone() },
  };

  const dome = new THREE.Mesh(
    new THREE.SphereGeometry(600, 48, 24),
    new THREE.ShaderMaterial({
      uniforms,
      vertexShader: SKY_VERT,
      fragmentShader: SKY_FRAG,
      side: THREE.BackSide,
      depthWrite: false,
    }),
  );
  dome.frustumCulled = false;
  dome.renderOrder = -10;
  group.add(dome);

  // sun disc + halo
  const sunPos = sunDir.clone().multiplyScalar(520);
  const disc = new THREE.Mesh(
    new THREE.CircleGeometry(20, 48),
    new THREE.MeshBasicMaterial({
      color: 0xfff6dd,
      depthWrite: false,
      transparent: true,
      opacity: 0.98,
    }),
  );
  disc.position.copy(sunPos);
  disc.renderOrder = -9;
  group.add(disc);

  const glow = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: makeGlowTexture(),
      color: 0xffe2b0,
      transparent: true,
      opacity: 0.75,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    }),
  );
  glow.position.copy(sunPos);
  glow.scale.setScalar(320);
  glow.renderOrder = -9;
  group.add(glow);

  // drifting cumulus clouds
  const cloudTex = makeCloudTexture(11);
  const clouds = [];
  const cloudSpecs = [
    [-260, 58, -300, 230, 96],
    [220, 44, -340, 260, 104],
    [-120, 92, -380, 200, 78],
    [330, 86, -180, 190, 74],
    [-360, 40, -60, 210, 82],
    [90, 110, -420, 240, 88],
    [-40, 62, -330, 170, 66],
    [380, 52, 60, 180, 70],
  ];
  for (const [x, y, z, w, h] of cloudSpecs) {
    const sprite = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: cloudTex,
        transparent: true,
        opacity: 0.62 + Math.random() * 0.2,
        depthWrite: false,
      }),
    );
    sprite.position.set(x, y, z);
    sprite.scale.set(w, h, 1);
    group.add(sprite);
    clouds.push({ sprite, drift: 0.7 + Math.random() * 1.1, baseY: y });
  }

  // distant gulls, slowly circling
  const gulls = [];
  const gullGeo = new THREE.SphereGeometry(1, 10, 8);
  const wingGeo = new THREE.BoxGeometry(1, 0.06, 0.32);
  for (let i = 0; i < 5; i++) {
    const gull = new THREE.Group();
    const body = new THREE.Mesh(gullGeo);
    body.scale.setScalar(0.34 + i * 0.03);
    body.scale.z *= 2.2;
    gull.add(body);

    const mat = new THREE.ShaderMaterial({
      uniforms: {
        uColor: { value: new THREE.Color(i % 2 ? 0xf2f4f2 : 0xdfe3e0) },
        uSunDir: { value: sunDir.clone() },
        uSkyTop: { value: new THREE.Color(palette.skyTop) },
        uHorizon: { value: new THREE.Color(palette.skyHorizon) },
      },
      vertexShader: GULL_VERT,
      fragmentShader: GULL_FRAG,
      side: THREE.DoubleSide,
    });
    body.material = mat;

    const wings = [];
    for (const side of [-1, 1]) {
      const pivot = new THREE.Group();
      pivot.position.x = side * 0.22;
      const wing = new THREE.Mesh(wingGeo, mat);
      wing.position.x = side * 0.75;
      wing.scale.set(1.5, 1, 1);
      pivot.add(wing);
      gull.add(pivot);
      wings.push({ pivot, side });
    }

    const radius = 55 + i * 26;
    const height = 16 + (i % 3) * 9;
    const phase = i * 1.7;
    const speed = 0.045 + i * 0.008;
    group.add(gull);
    gulls.push({ gull, wings, radius, height, phase, speed });
  }

  return {
    group,
    update(t) {
      for (const c of clouds) {
        c.sprite.position.x += c.drift * 0.012;
        c.sprite.position.y = c.baseY + Math.sin(t * 0.12 + c.drift * 3) * 1.6;
        if (c.sprite.position.x > 480) c.sprite.position.x = -480;
      }
      for (const g of gulls) {
        const a = g.phase + t * g.speed;
        g.gull.position.set(
          Math.cos(a) * g.radius,
          g.height + Math.sin(a * 2.1) * 1.8,
          Math.sin(a) * g.radius - 60,
        );
        g.gull.rotation.y = -a + Math.PI / 2;
        const flap = Math.sin(t * 3.4 + g.phase * 2) * 0.62;
        for (const w of g.wings) w.pivot.rotation.z = w.side * flap;
      }
    },
  };
}

import * as THREE from 'three';
import { waveHeight, waveNormal } from './waves.js';

// Local frame convention: +Z = forward (direction of travel), +Y = up.

const C = {
  body: 0xf6f1e4,
  breast: 0xfbf7ec,
  shade: 0xdfe2dc,
  wing: 0xece7d8,
  wingTip: 0xb6c0c4,
  beakTop: 0xef9f36,
  beakLow: 0xe08a2c,
  pouch: 0xf6a23e,
  leg: 0xe8862c,
  eye: 0x221a15,
  eyeRing: 0xf1d69b,
  board: 0xf4f2ee,
  boardStripe: 0xe2583d,
  boardRail: 0x27536d,
  fin: 0x1d3d52,
};

function std(color, roughness = 0.7, extra = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness,
    metalness: 0,
    ...extra,
  });
}

/** Extrude a flat shape so it lies in the XZ plane: X = length, Z = chord, Y = thickness. */
function extrudeFlat(shape, { depth = 0.1, bevel = 0.05, segments = 24 } = {}) {
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: bevel > 0,
    bevelThickness: bevel,
    bevelSize: bevel,
    bevelSegments: 4,
    curveSegments: segments,
  });
  geo.translate(0, 0, -depth / 2);
  geo.rotateX(Math.PI / 2);
  return geo;
}

/** Rounded leaf/feather shape, length along +X, width along Y. */
function featherShape(length, width) {
  const s = new THREE.Shape();
  s.moveTo(0, 0);
  s.bezierCurveTo(
    length * 0.28,
    width * 0.56,
    length * 0.72,
    width * 0.52,
    length,
    0,
  );
  s.bezierCurveTo(
    length * 0.72,
    -width * 0.52,
    length * 0.28,
    -width * 0.56,
    0,
    0,
  );
  return s;
}

function featherGeometry(length, width, depth = 0.055) {
  return extrudeFlat(featherShape(length, width), {
    depth,
    bevel: depth * 0.6,
    segments: 18,
  });
}

function buildBoard() {
  const group = new THREE.Group();
  const L = 2.15;
  const W = 0.62;

  const outline = new THREE.Shape();
  outline.moveTo(L, 0);
  outline.bezierCurveTo(L * 0.96, W * 0.52, L * 0.52, W * 0.96, 0, W);
  outline.bezierCurveTo(-L * 0.56, W * 0.96, -L * 0.97, W * 0.56, -L * 0.99, 0);
  outline.bezierCurveTo(-L * 0.97, -W * 0.56, -L * 0.56, -W * 0.96, 0, -W);
  outline.bezierCurveTo(L * 0.52, -W * 0.96, L * 0.96, -W * 0.52, L, 0);

  const boardGeo = extrudeFlat(outline, {
    depth: 0.13,
    bevel: 0.075,
    segments: 44,
  });
  boardGeo.rotateY(-Math.PI / 2); // nose toward +Z

  // rocker: nose and tail curve up
  const applyRocker = (geo) => {
    const pos = geo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const z = pos.getZ(i);
      const t = z / L;
      pos.setY(i, pos.getY(i) + 0.2 * t * t + Math.max(0, t) * 0.1);
    }
    pos.needsUpdate = true;
    geo.computeVertexNormals();
    return geo;
  };
  applyRocker(boardGeo);

  const board = new THREE.Mesh(boardGeo, std(C.board, 0.42));
  group.add(board);

  // deck stripe
  const stripeShape = new THREE.Shape();
  stripeShape.moveTo(L * 0.86, 0);
  stripeShape.bezierCurveTo(L * 0.8, W * 0.3, L * 0.45, W * 0.42, 0, W * 0.42);
  stripeShape.bezierCurveTo(
    -L * 0.5,
    W * 0.42,
    -L * 0.82,
    W * 0.26,
    -L * 0.86,
    0,
  );
  stripeShape.bezierCurveTo(
    -L * 0.82,
    -W * 0.26,
    -L * 0.5,
    -W * 0.42,
    0,
    -W * 0.42,
  );
  stripeShape.bezierCurveTo(L * 0.45, -W * 0.42, L * 0.8, -W * 0.3, L * 0.86, 0);
  const stripeGeo = extrudeFlat(stripeShape, {
    depth: 0.012,
    bevel: 0.012,
    segments: 30,
  });
  stripeGeo.rotateY(-Math.PI / 2);
  stripeGeo.translate(0, 0.128, 0);
  applyRocker(stripeGeo);
  group.add(new THREE.Mesh(stripeGeo, std(C.boardStripe, 0.5)));

  // thin rail line for contrast
  const railShape = new THREE.Shape();
  railShape.absellipse(0, 0, L * 0.985, W * 1.005, 0, Math.PI * 2, false, 0);
  const railGeo = extrudeFlat(railShape, {
    depth: 0.008,
    bevel: 0.008,
    segments: 48,
  });
  const railHole = new THREE.Path();
  railHole.absellipse(0, 0, L * 0.955, W * 0.965, 0, Math.PI * 2, true, 0);
  railShape.holes.push(railHole);
  railGeo.rotateY(-Math.PI / 2);
  railGeo.translate(0, 0.115, 0);
  applyRocker(railGeo);
  group.add(new THREE.Mesh(railGeo, std(C.boardRail, 0.45)));

  // fins
  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.lineTo(-0.6, 0);
  finShape.bezierCurveTo(-0.5, 0.24, -0.4, 0.42, -0.3, 0.5);
  finShape.lineTo(-0.18, 0.5);
  finShape.bezierCurveTo(-0.13, 0.34, -0.06, 0.16, 0, 0);
  const finGeo = extrudeFlat(finShape, { depth: 0.055, bevel: 0.02, segments: 16 });
  finGeo.rotateZ(Math.PI); // fin points down
  const finMat = std(C.fin, 0.45);
  const finSpecs = [
    [0, -0.12, -1.28, 0],
    [0.3, -0.11, -1.12, -0.22],
    [-0.3, -0.11, -1.12, 0.22],
  ];
  for (const [x, y, z, ry] of finSpecs) {
    const fin = new THREE.Mesh(finGeo, finMat);
    fin.position.set(x, y, z);
    fin.rotation.y = ry;
    group.add(fin);
  }

  return group;
}

function buildWing(side) {
  const group = new THREE.Group();
  const shape = new THREE.Shape();
  shape.moveTo(0, 0.3);
  shape.bezierCurveTo(0.85, 0.42, 1.75, 0.34, 2.42, 0.06);
  shape.bezierCurveTo(2.66, -0.03, 2.62, -0.2, 2.28, -0.28);
  shape.bezierCurveTo(1.5, -0.54, 0.62, -0.6, 0, -0.48);
  shape.closePath();

  const geo = extrudeFlat(shape, { depth: 0.11, bevel: 0.055, segments: 26 });
  if (side < 0) geo.scale(-1, 1, 1);
  const matWing = std(C.wing, 0.82, { side: THREE.DoubleSide });
  const matTip = std(C.wingTip, 0.85, { side: THREE.DoubleSide });
  group.add(new THREE.Mesh(geo, matWing));

  // primary feathers at the wing tip
  const featherGeo = featherGeometry(1.15, 0.34, 0.05);
  const angles = [0.22, 0.06, -0.12, -0.3];
  for (let i = 0; i < angles.length; i++) {
    const feather = new THREE.Mesh(featherGeo, matTip);
    const x = side * (1.35 + i * 0.3);
    feather.position.set(x, -0.02 - i * 0.012, -0.22 - i * 0.1);
    feather.rotation.y = side * (-Math.PI / 2 + angles[i] * 0.5 + 0.18);
    feather.rotation.z = side * 0.06;
    group.add(feather);
  }
  return group;
}

function buildFoot() {
  const s = new THREE.Shape();
  s.moveTo(-0.15, -0.3);
  s.lineTo(-0.31, 0.28);
  s.quadraticCurveTo(-0.23, 0.43, -0.13, 0.31);
  s.lineTo(-0.07, 0.16);
  s.lineTo(-0.03, 0.45);
  s.quadraticCurveTo(0.03, 0.55, 0.1, 0.4);
  s.lineTo(0.13, 0.19);
  s.lineTo(0.29, 0.29);
  s.quadraticCurveTo(0.37, 0.2, 0.25, 0.1);
  s.lineTo(0.15, -0.3);
  s.closePath();
  return extrudeFlat(s, { depth: 0.055, bevel: 0.028, segments: 12 });
}

function buildPelican() {
  const bird = new THREE.Group();
  const matBody = std(C.body, 0.78);
  const matBreast = std(C.breast, 0.82);
  const matShade = std(C.shade, 0.8);
  const matBeakTop = std(C.beakTop, 0.42);
  const matBeakLow = std(C.beakLow, 0.5);
  const matPouch = std(C.pouch, 0.52);
  const matLeg = std(C.leg, 0.6);
  const matEye = std(C.eye, 0.28);
  const matEyeRing = std(C.eyeRing, 0.72);

  // body
  const bodyGeo = new THREE.SphereGeometry(1, 40, 28);
  const body = new THREE.Mesh(bodyGeo, matBody);
  body.position.set(0, 1.62, -0.02);
  body.scale.set(0.9, 0.98, 1.42);
  body.rotation.x = 0.16;
  bird.add(body);

  const breast = new THREE.Mesh(bodyGeo, matBreast);
  breast.position.set(0, 1.34, 0.58);
  breast.scale.set(0.78, 0.84, 0.92);
  breast.rotation.x = 0.32;
  bird.add(breast);

  // tail feathers
  const tailGeo = featherGeometry(1.05, 0.42, 0.06);
  for (let i = -1; i <= 1; i++) {
    const tail = new THREE.Mesh(tailGeo, matShade);
    tail.position.set(i * 0.11, 1.72, -1.28);
    tail.rotation.y = Math.PI / 2 + i * 0.22;
    tail.rotation.x = 0.34;
    tail.rotation.z = i * 0.1;
    bird.add(tail);
  }

  // legs + webbed feet
  const legGeo = new THREE.CylinderGeometry(0.085, 0.1, 0.9, 12);
  const footGeo = buildFoot();
  for (const side of [-1, 1]) {
    const leg = new THREE.Mesh(legGeo, matLeg);
    leg.position.set(side * 0.33, 0.72, 0.28);
    leg.rotation.x = 0.3;
    leg.rotation.z = side * -0.1;
    bird.add(leg);

    const foot = new THREE.Mesh(footGeo, matLeg);
    foot.position.set(side * 0.36, 0.135, 0.52);
    foot.rotation.y = side * 0.3;
    foot.rotation.x = -0.06;
    bird.add(foot);
  }

  // neck
  const neckCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, 2.0, 0.5),
    new THREE.Vector3(0, 2.5, 0.68),
    new THREE.Vector3(0, 2.92, 1.06),
    new THREE.Vector3(0, 3.18, 1.42),
  ]);
  const neck = new THREE.Mesh(
    new THREE.TubeGeometry(neckCurve, 36, 0.275, 16, false),
    matBody,
  );
  bird.add(neck);

  const nape = new THREE.Mesh(bodyGeo, matBody);
  nape.position.set(0, 1.95, 0.5);
  nape.scale.set(0.42, 0.5, 0.55);
  bird.add(nape);

  // head
  const head = new THREE.Group();
  head.position.set(0, 3.3, 1.6);
  bird.add(head);

  const skull = new THREE.Mesh(bodyGeo, matBody);
  skull.scale.set(0.4, 0.42, 0.47);
  head.add(skull);

  const crown = new THREE.Mesh(bodyGeo, matShade);
  crown.position.set(0, 0.12, -0.16);
  crown.scale.set(0.3, 0.22, 0.3);
  head.add(crown);

  // beak
  const beak = new THREE.Group();
  beak.position.set(0, -0.08, 0.28);
  beak.rotation.x = 0.1;
  head.add(beak);

  const upperGeo = new THREE.CylinderGeometry(0.05, 0.3, 1.5, 14);
  upperGeo.rotateX(Math.PI / 2);
  upperGeo.scale(0.86, 0.52, 1);
  const upper = new THREE.Mesh(upperGeo, matBeakTop);
  upper.position.set(0, 0.1, 0.72);
  beak.add(upper);

  const hookGeo = new THREE.ConeGeometry(0.085, 0.3, 12);
  hookGeo.rotateX(Math.PI / 2 + 0.55);
  const hook = new THREE.Mesh(hookGeo, matBeakTop);
  hook.position.set(0, 0.02, 1.5);
  beak.add(hook);

  const lowerGeo = new THREE.CylinderGeometry(0.045, 0.16, 1.28, 12);
  lowerGeo.rotateX(Math.PI / 2);
  lowerGeo.scale(0.72, 0.34, 1);
  const lower = new THREE.Mesh(lowerGeo, matBeakLow);
  lower.position.set(0, -0.08, 0.6);
  beak.add(lower);

  const pouch = new THREE.Mesh(bodyGeo, matPouch);
  pouch.position.set(0, -0.32, 0.56);
  pouch.scale.set(0.31, 0.42, 0.84);
  beak.add(pouch);

  // eyes
  for (const side of [-1, 1]) {
    const ring = new THREE.Mesh(bodyGeo, matEyeRing);
    ring.position.set(side * 0.35, 0.085, 0.12);
    ring.scale.set(0.075, 0.16, 0.19);
    head.add(ring);

    const eye = new THREE.Mesh(bodyGeo, matEye);
    eye.position.set(side * 0.382, 0.09, 0.165);
    eye.scale.setScalar(0.082);
    head.add(eye);

    const glint = new THREE.Mesh(
      bodyGeo,
      new THREE.MeshBasicMaterial({ color: 0xffffff }),
    );
    glint.position.set(side * 0.408, 0.125, 0.208);
    glint.scale.setScalar(0.026);
    head.add(glint);
  }

  return { bird, head, beak, pouch };
}

function buildWings() {
  const holder = new THREE.Group();
  const right = buildWing(1);
  const left = buildWing(-1);
  right.position.set(0.52, 1.95, 0.1);
  left.position.set(-0.52, 1.95, 0.1);
  holder.add(right, left);
  return { holder, right, left };
}

export function createSurfer() {
  const root = new THREE.Group();
  const ride = new THREE.Group();
  root.add(ride);

  const board = buildBoard();
  ride.add(board);

  const { bird, head, beak, pouch } = buildPelican();
  const { holder: wings, right: wingR, left: wingL } = buildWings();
  bird.add(wings);
  ride.add(bird);

  root.traverse((obj) => {
    if (obj.isMesh) {
      obj.castShadow = true;
      obj.receiveShadow = true;
    }
  });

  // scratch objects reused every frame
  const up = new THREE.Vector3();
  const fwd = new THREE.Vector3();
  const right = new THREE.Vector3();
  const normal = { x: 0, y: 1, z: 0 };
  const basis = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const qRoll = new THREE.Quaternion();
  const qPitch = new THREE.Quaternion();
  const qYaw = new THREE.Quaternion();
  const Z_AXIS = new THREE.Vector3(0, 0, 1);
  const X_AXIS = new THREE.Vector3(1, 0, 0);
  const Y_AXIS = new THREE.Vector3(0, 1, 0);
  const UP = new THREE.Vector3(0, 1, 0);
  const wakeLocal = new THREE.Vector3(0, 0.16, -1.95);
  const wakeWorld = new THREE.Vector3();

  const state = {
    position: new THREE.Vector3(),
    forward: new THREE.Vector3(0, 0, 1),
  };

  function update(t) {
    // glide path: a lazy line across the wave face
    const x = Math.sin(t * 0.21) * 1.55 + Math.sin(t * 0.37) * 0.55;
    const z = Math.cos(t * 0.16) * 1.25 + Math.sin(t * 0.27) * 0.45;
    const yaw = -0.62 + Math.sin(t * 0.19) * 0.24 + Math.sin(t * 0.33) * 0.09;

    waveNormal(x, z, t, normal);
    const h = waveHeight(x, z, t);

    // sit on the surface, tilted with the wave face
    up.set(normal.x, normal.y, normal.z).lerp(UP, 0.45).normalize();
    fwd.set(Math.sin(yaw), 0, Math.cos(yaw));
    fwd.addScaledVector(up, -fwd.dot(up)).normalize();
    right.crossVectors(up, fwd).normalize();
    basis.makeBasis(right, up, fwd);
    q.setFromRotationMatrix(basis);

    const roll = -0.13 + Math.sin(t * 0.53) * 0.11 + Math.sin(t * 0.29) * 0.05;
    const pitch =
      -0.06 + (h - waveHeight(x + fwd.x * 2.2, z + fwd.z * 2.2, t)) * 0.12;
    qRoll.setFromAxisAngle(Z_AXIS, roll);
    qPitch.setFromAxisAngle(X_AXIS, pitch);
    q.multiply(qRoll).multiply(qPitch);

    root.quaternion.copy(q);
    root.position.set(x, h + 0.11, z);

    // ---- secondary motion ----
    const bob = Math.sin(t * 1.9) * 0.035 + Math.sin(t * 3.1) * 0.018;
    ride.position.y = bob;
    ride.rotation.z = Math.sin(t * 0.61) * 0.035;
    ride.rotation.x = Math.sin(t * 0.47 + 1.2) * 0.03;

    bird.position.y = 0.02 + Math.sin(t * 1.35) * 0.03;
    bird.rotation.y = Math.sin(t * 0.41) * 0.14 + Math.sin(t * 0.9) * 0.05;
    bird.rotation.x = 0.1 + Math.sin(t * 1.1) * 0.035;

    // head: looking down the line, occasional glances
    const glance = Math.sin(t * 0.33) * 0.32 + Math.sin(t * 0.83) * 0.12;
    head.rotation.y = glance;
    head.rotation.x = -0.06 + Math.sin(t * 0.72) * 0.07;

    // wings: held out for balance, with gentle flaps
    const flap = Math.sin(t * 2.35) * 0.16 + Math.sin(t * 0.71) * 0.12;
    const lift = 0.16 + flap;
    const sweep = 0.4 + Math.sin(t * 1.15) * 0.14;
    wingR.rotation.set(Math.sin(t * 1.7) * 0.05, sweep, lift);
    wingL.rotation.set(Math.sin(t * 1.7) * 0.05, -sweep, -lift);

    // pouch jiggle
    const puff = 1 + Math.sin(t * 2.2) * 0.05 + Math.sin(t * 0.9) * 0.03;
    pouch.scale.set(0.31 * puff, 0.42 / puff, 0.84);
    beak.rotation.x = 0.1 + Math.sin(t * 0.65) * 0.045;

    state.position.copy(root.position);
    state.forward.copy(fwd);
  }

  function getWakePoint(target) {
    wakeWorld.copy(wakeLocal);
    root.localToWorld(wakeWorld);
    return (target || wakeWorld).copy(wakeWorld);
  }

  return { root, update, getWakePoint, state };
}

